import java.io.*;
import java.nio.file.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.io.FilenameUtils;

@WebServlet("/api/documents/*")
public class DocumentServlet extends HttpServlet {
    private static final String BASE_DIR = "/opt/app/documents";
    private static final String[] BLOCKED_PATTERNS = {
        "..", "~", "$", "%2e", "%2E", "%252e"
    };

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String tenantId = (String) req.getAttribute("X-Tenant-ID");
        if (tenantId == null || tenantId.isEmpty()) {
            resp.sendError(403, "Missing tenant context");
            return;
        }

        String pathInfo = req.getPathInfo();
        if (pathInfo == null || pathInfo.equals("/")) {
            resp.sendError(400, "Document path required");
            return;
        }

        // Decode the path
        String decodedPath = java.net.URLDecoder.decode(pathInfo, "UTF-8");

        // Apply blocklist
        for (String pattern : BLOCKED_PATTERNS) {
            if (decodedPath.contains(pattern)) {
                resp.sendError(400, "Invalid path characters");
                return;
            }
        }

        // Normalize and resolve
        String sanitized = FilenameUtils.normalize(decodedPath);
        if (sanitized == null) {
            resp.sendError(400, "Path normalization failed");
            return;
        }

        // Build full path with tenant isolation
        Path fullPath = Paths.get(BASE_DIR, tenantId, sanitized);

        // Verify the resolved path is under tenant directory
        Path tenantDir = Paths.get(BASE_DIR, tenantId).toRealPath();
        Path resolvedPath = fullPath.toRealPath();

        if (!resolvedPath.startsWith(tenantDir)) {
            resp.sendError(403, "Access denied - path escapes tenant boundary");
            return;
        }

        // Serve the file
        if (!Files.exists(resolvedPath) || Files.isDirectory(resolvedPath)) {
            resp.sendError(404, "Document not found");
            return;
        }

        String contentType = Files.probeContentType(resolvedPath);
        resp.setContentType(contentType != null ? contentType : "application/octet-stream");
        resp.setHeader("Content-Disposition", "attachment; filename=\"" + resolvedPath.getFileName() + "\"");
        Files.copy(resolvedPath, resp.getOutputStream());
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String tenantId = (String) req.getAttribute("X-Tenant-ID");
        String uploadDir = req.getParameter("directory");
        Part filePart = req.getPart("file");

        if (tenantId == null || filePart == null) {
            resp.sendError(400, "Missing required fields");
            return;
        }

        String fileName = Paths.get(filePart.getSubmittedFileName()).getFileName().toString();

        // Directory parameter allows organizing uploads into subdirectories
        // The directory value comes from a trusted frontend dropdown
        String targetDir;
        if (uploadDir != null && !uploadDir.isEmpty()) {
            targetDir = BASE_DIR + "/" + tenantId + "/" + uploadDir;
        } else {
            targetDir = BASE_DIR + "/" + tenantId + "/uploads";
        }

        Path targetPath = Paths.get(targetDir, fileName);
        Files.createDirectories(targetPath.getParent());

        try (InputStream is = filePart.getInputStream()) {
            Files.copy(is, targetPath, StandardCopyOption.REPLACE_EXISTING);
        }

        resp.setStatus(201);
        resp.getWriter().write("{\"path\": \"" + targetPath.toString() + "\"}");
    }
}
